import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, m] = lines[0].split(" ").map(Number);
const graph: number[][] = Array.from({ length: n + 1 }, () => []);
const reversed: number[][] = Array.from({ length: n + 1 }, () => []);
for (let i = 1; i <= m; i++) {
  const [u, v] = lines[i].split(" ").map(Number);
  graph[u].push(v);
  reversed[v].push(u);
}

// 1 回目: 元のグラフで DFS し、抜けた順（帰りがけ順）に頂点を記録する
const visited = new Uint8Array(n + 1);
const order: number[] = [];
const edgeIndex = new Int32Array(n + 1);
for (let s = 1; s <= n; s++) {
  if (visited[s]) continue;
  visited[s] = 1;
  const stack = [s];
  while (stack.length > 0) {
    const v = stack[stack.length - 1];
    if (edgeIndex[v] < graph[v].length) {
      const next = graph[v][edgeIndex[v]++];
      if (!visited[next]) {
        visited[next] = 1;
        stack.push(next);
      }
    } else {
      order.push(v);
      stack.pop();
    }
  }
}

// 2 回目: 帰りがけ順の遅い頂点から、逆向きのグラフで到達できる範囲が 1 つの成分
const component = new Int32Array(n + 1).fill(-1);
let count = 0;
for (let i = order.length - 1; i >= 0; i--) {
  const s = order[i];
  if (component[s] !== -1) continue;
  component[s] = count;
  const stack = [s];
  while (stack.length > 0) {
    const v = stack.pop()!;
    for (const next of reversed[v]) {
      if (component[next] !== -1) continue;
      component[next] = count;
      stack.push(next);
    }
  }
  count++;
}
console.log(count);
